import { Field, FieldLabel } from "@/registry/erbium/ui/field";
import { Icon } from "@/registry/erbium/ui/icon";
import { InputGroupAddon } from "@/registry/erbium/ui/input-group";
import {
  PasswordInputControl,
  PasswordInputRoot,
  PasswordInputToggle,
} from "@/registry/erbium/ui/password-input";

export default function PasswordInputCustomExample() {
  return (
    <Field className="max-w-sm">
      <FieldLabel>Vault passphrase</FieldLabel>
      <PasswordInputRoot>
        <PasswordInputControl placeholder="Enter your passphrase" />
        <InputGroupAddon>
          <Icon name="lock" />
        </InputGroupAddon>
        <InputGroupAddon align="inline-end">
          <PasswordInputToggle aria-label="Show passphrase" />
        </InputGroupAddon>
      </PasswordInputRoot>
    </Field>
  );
}

import PasswordInputCustom from "../examples/password-input-custom";

const Example = () => <PasswordInputCustom />;

export default Example;
